package api

var sswCurriculumLinenSupplyCautionsEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.caution", source: `Hindari permukaan panas, uap, dan bagian bergerak; gunakan perlindungan serta prosedur fasilitas.`}:           `Keep clear of hot surfaces, steam, and moving parts; use the required protective equipment and facility procedures.`,
	{field: "ssw.caution", source: `Jangan menaruh linen bersih pada wadah yang belum dinyatakan bersih.`}:                                        `Do not place clean linen in a container that has not been confirmed clean.`,
	{field: "ssw.caution", source: `Jangan mencampur bahan kimia atau memindahkannya ke botol tanpa label.`}:                                      `Do not mix chemicals or transfer them to an unlabeled bottle.`,
	{field: "ssw.caution", source: `Jangan mencampur kelompok hanya karena warna, ukuran, atau bentuknya tampak serupa.`}:                         `Do not mix lots just because their color, size, or shape looks similar.`,
	{field: "ssw.caution", source: `Jangan mencampur linen kotor dengan barang selesai atau mengubah alur tanpa persetujuan.`}:                    `Do not mix soiled linen with finished items or change the flow without approval.`,
	{field: "ssw.caution", source: `Jangan menebak dosis bahan atau menyentuh bahan kimia tanpa pelatihan dan perlindungan yang dipersyaratkan.`}: `Do not guess chemical doses or handle chemicals without the required training and protective equipment.`,
	{field: "ssw.caution", source: `Jangan menghapus tanda tahan atau melaporkan pekerjaan selesai tanpa konfirmasi.`}:                            `Do not remove a hold label or report a task complete without confirmation.`,
	{field: "ssw.caution", source: `Jangan mengubah catatan agar cocok dengan angka target atau mengabaikan selisih kecil.`}:                      `Do not alter records to match a target figure or disregard a small discrepancy.`,
	{field: "ssw.caution", source: `Jangan mengubah jumlah bundel atau label untuk menutup kekurangan barang.`}:                                   `Do not change bundle counts or labels to conceal a shortage.`,
	{field: "ssw.caution", source: `Jangan mengubah kriteria mutu sendiri atau melewatkan pemeriksaan saat lini sibuk.`}:                          `Do not change quality criteria on your own or skip an inspection when the line is busy.`,
	{field: "ssw.caution", source: `Jangan menjangkau mesin aktif, menonaktifkan interlock, atau memperbaiki bagian listrik tanpa kewenangan.`}:   `Do not reach into a running machine, disable an interlock, or repair electrical parts without authorization.`,
	{field: "ssw.caution", source: `Pemasukan ke mesin dilakukan setelah pelatihan alat; jangan menjangkau sabuk atau bagian bergerak.`}:          `Feed items into the machine only after equipment training; never reach toward belts or moving parts.`,
}

